def _signature(question):
    raw = '\0'.join((question.module, question.text, question.code_snippet))
    return hashlib.sha256(raw.encode('utf-8')).hexdigest()


def assign_objectives(apps, schema_editor):
    Question = apps.get_model('quiz', 'Question')
    questions = list(Question.objects.all().only('id', 'module', 'text', 'code_snippet'))
    unknown_ids = []
    for question in questions:
        objective = OBJECTIVE_BY_SIGNATURE.get(_signature(question))
        if objective is None:
            unknown_ids.append(question.id)
        else:
            question.objective = objective
    if unknown_ids:
        raise RuntimeError(
            'Cannot assign a reviewed syllabus objective to question IDs: '
            + ', '.join(str(value) for value in unknown_ids)
        )
    if questions:
        Question.objects.bulk_update(questions, ['objective'])


